			["actions"] = {
				["start"] = {
				},
				["init"] = {
					["custom"] = "C_ChatInfo.RegisterAddonMessagePrefix(\"BWLElemShields\")\n\naura_env.mobID = {\n    [12460] = \"Wyrmguard\",\n    [12461] = \"Overseer\",\n    [14020] = \"Chromaggus\",\n}\n\naura_env.weaknessTable = {\n    [22277] = \"Fire\",\n    [22278] = \"Frost\",\n    [22279] = \"Shadow\",\n    [22280] = \"Nature\",\n    [22281] = \"Arcane\",\n}\n\naura_env.version = 4\n\naura_env.versionWhitelist = {\n    [1] = false,\n    [2] = false,\n    [3] = true\n}\n\naura_env.versionWhitelist[aura_env.version] = true\n\naura_env.UpdateState = function(allstates, GUID, mobName, weakness, icon, targetted)\n    local nameplate = nil\n    for i = 1,40 do\n        local token = \"nameplate\"..i\n        local tokenGUID = UnitGUID(token)\n        if not tokenGUID then break end\n        if tokenGUID == GUID then\n            nameplate = token\n        end\n    end\n    \n    if allstates[GUID] then\n        allstates[GUID].changed = true\n        allstates[GUID].mobName = mobName\n        allstates[GUID].weakness = weakness\n        allstates[GUID].raidIcon = icon\n        allstates[GUID].nameplate = nameplate\n        if targetted ~= nil then\n            allstates[GUID].targetted = targetted\n            if aura_env.config.announce and allstates[GUID].show then\n                if allstates[GUID].weakness ~= allstates[GUID].oldWeakness and allstates[GUID].show then\n                    allstates[GUID].oldWeakness = weakness\n                    if weakness ~= \"Unknown\" then\n                        SendChatMessage(icon..mobName..\": \"..weakness, \"SAY\")\n                    elseif mobName == \"Chromaggus\" then\n                        SendChatMessage(icon..mobName..\": Detect Magic required\", \"SAY\")\n                    end\n                end\n            end\n        end\n    else\n        allstates[GUID] = {\n            show = true,\n            changed = true,\n            progressType = \"static\",\n            value = 1,\n            total = 1,\n            mobName = mobName,\n            oldWeakness = weakness,\n            weakness = weakness,\n            raidIcon = icon,\n            nameplate = nameplate,\n            targetted = targetted\n        }\n        if aura_env.config.announce and targetted ~= nil and weakness ~= \"Unknown\" then\n            SendChatMessage(icon..mobName..\": \"..weakness, \"SAY\")\n        end\n    end\nend",
